INSERT INTO `posts` VALUES
('p1789830710891','1','무명','누비다','bf_ec7c8e341da4449a','f1','수진','/static/mr/Sunny Days - Anno Domini Beats.mp3','[{\"text\": \"AI 힙합 스튜디오에 오신 것을 환영합니다.\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0}]',0,'pbkdf2_sha256$260000$Oj4AlWoZraEHYBq4iK/+9A==$HZjvJ2KYjl4cvltWkUJmKKkadEvPod+lsW9gZcXC/e4=','2026-09-19 15:16:53'),
('p1790910090689','우정','관리자','NBD2','bf_f4c539b69fb44326','f1','수진','/static/assets/uploads/songs/145d6246-8da8-4f04-bd4d-6aaf7e8da81a.mp3?t=1790910076166','[]',2,'pbkdf2_sha256$260000$FLD3C0wnY2rDusEb8bHdeg==$G36ah1AcpweWMgQgKhnxWWNGvn8h+YWJ7lh0NrVLvo4=','2026-10-02 03:06:57'),
('p1790990344815','가을','무명','누비다','bf_ec7c8e341da4449a','f1','수진','/static/mr/Boom - Dyalla.mp3','[{\"text\": \"AI 힙합 스튜디오에 오신 것을 환영합니다.\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.3, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.9}, {\"text\": \"가을의  청량한 느낌\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1, \"wait\": 0.3, \"filter\": 0, \"pan\": 0, \"grit\": 0}]',0,'pbkdf2_sha256$260000$ScD6H188aS5uF2iGBi1fuQ==$cNA+Y++VBB1EIztZ2Lzm17CRpH3A6cbcMOF+baKiWFs=','2026-10-03 01:19:04'),
('p1790990372152','모이세','Ysk','누비다','bf_ec7c8e341da4449a','f2','민서','/static/mr/Trilogy - Telecasted.mp3','[{\"text\": \"동쪽 끝에서 부르는 소리 대한의 한 가락 오늘 밤 모이세\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.4}, {\"text\": \"    전국 곳곳에서 들려오는 소리로 사람들을 부름 밤 모이세\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.4}, {\"text\": \"꿈을 향해 끝없이 달리자\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.4}, {\"text\": \"모이세의 불꽃이 우리를 태워\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.4}, {\"text\": \"지금은 나도 너도 함께 떠나\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.4}, {\"text\": \"이 세상은 우리 손으로 바꾸자\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.4}, {\"text\": \"함께 만들어 가는 미래의 길\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.2, \"wait\": 0.2, \"filter\": 0, \"pan\": 0, \"grit\": 0.4}]',0,'pbkdf2_sha256$260000$CHDV3PxmjuPArJtNiuIFCQ==$CoUNdfscdn8O8moZYIxPvHXwYm1HJ2J4bCaUZu3bsFc=','2026-10-03 01:19:32'),
('p1790990723293','무지개','Ysk','NBD2','bf_f4c539b69fb44326','f2','민서','/static/assets/uploads/songs/75455714-dd5a-4de9-8ee8-d51ef36073b0.mp3?t=1790990646388','[]',1,'pbkdf2_sha256$260000$dwS7JKeBNkFJWl9A5pjSow==$6di6uQCKEdvtyzE/Bll6149RNNtSJDDeOwBWS2te68M=','2026-10-03 01:25:23');
INSERT INTO `posts_bak_260914` VALUES
('p1770492187096','샘플중학교','김샘플','샘플중학교','f1','수진','/static/mr/Boom - Dyalla.mp3','[{\"text\": \"AI 힙합 스튜디오에 오신 것을 환영합니다.\", \"tune\": \"18\", \"echo\": \"0.1\", \"speed\": \"1.2\", \"wait\": \"0.2\"}]',16,'1234','2026-02-07 19:18:31'),
('p1771908813573','유쌤행복한노래','유쌤','샘플중학교','f3','유나','/static/mr/Sunny Days - Anno Domini Beats.mp3','[{\"text\": \"아침 햇살처럼 웃는 얼굴이 가득해 세상 모든 걱정은 멀어져 하루의 시작이 이렇게 아름다울 수 없네 \", \"tune\": 4, \"echo\": 0.1, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"별빛 아래서 노래하듯 손뼉 치는 즐거움이 넘쳐 자유롭게 날아오르네 하늘을 향해 날아가봐\", \"tune\": 5, \"echo\": 0, \"speed\": 0.6, \"wait\": 0.3}, {\"text\": \"햇살 가득한 미소 그 미소는 나를 감싸고 희망이 가득 찬 길 나아가며 행복을 찾아\", \"tune\": 4, \"echo\": 0.4, \"speed\": 0.6, \"wait\": 0.2}]',5,'0709','2026-02-24 04:53:33'),
('p1772416109963','비가와서','무명','개인','f1','수진','/static/mr/Sunny Days - Anno Domini Beats.mp3','[{\"text\": \"비가 와서 생각이 났어\", \"tune\": 12, \"echo\": 0.1, \"speed\": 0.8, \"wait\": 0.2}, {\"text\": \"별일은 없고 그냥 조용했을 뿐\", \"tune\": 12, \"echo\": 0.2, \"speed\": 0.9, \"wait\": 0.3}, {\"text\": \"네 얘기라면 이쯤에서\", \"tune\": 11, \"echo\": 0.2, \"speed\": 1.3, \"wait\": 0.3}]',2,'1244','2026-03-02 01:48:30'),
('p1772417326631','그대곁에','무명','개인','f1','수진','/static/mr/Kicking It - Dyalla.mp3','[{\"text\": \"하늘 끝까지 reach한 별처럼\", \"tune\": 10, \"echo\": 0.3, \"speed\": 1.1, \"wait\": 0.4}, {\"text\": \"어둠 속에서도 빛나는 네 모습\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.8, \"wait\": 0.4}, {\"text\": \"그대 곁에 서면 모든 게 아름답게 변해요\", \"tune\": 8, \"echo\": 0.1, \"speed\": 1.7, \"wait\": 0.4}, {\"text\": \"어둠이 찾아 오더라도, 네 눈빛이 비추어요\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.5, \"wait\": 0.4}, {\"text\": \"그대 곁에 서면 모든 슬픔이 사라지고\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.7, \"wait\": 0.3}, {\"text\": \"비 오는 날에도 빛나는 네 곁을 걸어요\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.6, \"wait\": 0.3}]',1,'1234','2026-03-02 02:08:47'),
('p1782460864882','영웅 송상현 부사','샤샤넬','샤넬초등학교','f2','민서','/static/mr/Cooked - Dyalla.mp3','[{\"text\": \"동래 성벽 위에 서, 조선 지키려 했네\", \"tune\": 3, \"echo\": 0.2, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"백성을 위해 불꽃처럼 빛나네\", \"tune\": 3, \"echo\": 0, \"speed\": 1.3, \"wait\": 0.3}, {\"text\": \"폭풍 속에서도 변치 않는 정의의 길\", \"tune\": 2, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"송상현의 이름은 빛나네\", \"tune\": 3, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"용감한정신,그의 유산은forever\", \"tune\": 3, \"echo\": 0, \"speed\": 1.1, \"wait\": 0.3}, {\"text\": \"그의 정신은 오늘까지 울려 퍼진다\", \"tune\": 8, \"echo\": 0, \"speed\": 1.1, \"wait\": 0.3}]',3,'segyejeon1012!','2026-06-26 08:01:05'),
('p1782461003951','하늘의 지혜 장영실의 꿈','손ㅇ서','명륜초','f4','서현','/static/mr/No Rush - Dyalla.mp3','[{\"text\": \"과학의 문을 열고 기술로 세상을 변화시켜\", \"tune\": 10, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.2}, {\"text\": \"장영실쳐럼 빛나는 너의 길을 찾아가렴\", \"tune\": 10, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}, {\"text\": \"별을 보고 배우는 마음 도전하는 마음을 잃지말고\", \"tune\": 10, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}, {\"text\": \"네 앞에는 무한한 기회가 널 기다리고 있어\", \"tune\": 10, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}, {\"text\": \"하늘의 비밀을 깨우치고 혁신의 불꽃을켜\", \"tune\": 10, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}]',1,'1234','2026-06-26 08:03:24'),
('p1782461058620','동래야류','김알렉산드로뾰뚜르비치','이음반','f3','유나','/static/mr/Boom - Dyalla.mp3','[{\"text\": \"동래의 밤하늘 별빛아래, 전통 위에 춤추네\", \"tune\": 11, \"echo\": 0, \"speed\": 1.1, \"wait\": 0.3}, {\"text\": \"야류의 리듬에 몸을 맡기며,\", \"tune\": 11, \"echo\": 0, \"speed\": 1.1, \"wait\": 0.3}, {\"text\": \"유희의 노래가 시작되네.\", \"tune\": 11, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"동래야류 화려한 춤으로 역사와 웃음이 함께하네\", \"tune\": 12, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"유래 깊은 이야기를 춤으로 펼쳐\", \"tune\": 8, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"문화의 숨결이 살아 움직이네\", \"tune\": 10, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}]',5,'3333','2026-06-26 08:04:18'),
('p1782461092915','별빛 부사 그는 누구인가','오늘 벨튀 야르','개인','f4','서현','/static/mr/Broken Circuits - Telecasted.mp3','[{\"text\": \"동래부사의 꿈을 품고 \", \"tune\": 4, \"echo\": 0, \"speed\": 1.1, \"wait\": 0.2}, {\"text\": \"먼 길을 걸어온 그의 발자국을\", \"tune\": 9, \"echo\": 0, \"speed\": 1.1, \"wait\": 0.3}, {\"text\": \"1527년 부터 부산동래부에.\", \"tune\": 8, \"echo\": 0, \"speed\": 1.2, \"wait\": 0.3}, {\"text\": \"송상현, 그 이름은 희망의 빛!\", \"tune\": 10, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"송상현의 꿈과 용기!\", \"tune\": 8, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"영원히 기억될 동래 부사여!\", \"tune\": 6, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}]',3,'1234','2026-06-26 08:04:54'),
('p1782461267935','동래구의 세 영웅','권촌으로 체육쌤 쏘기 1일차','개인','f5','은정','/static/mr/Cooked - Dyalla.mp3','[{\"text\": \"첫번째인물 박차정 \", \"tune\": 20, \"echo\": 0.7, \"speed\": 0.9, \"wait\": 1}, {\"text\": \"비긴날 위에 독립의 꿈을 품은 독립 운동가\", \"tune\": 20, \"echo\": 0, \"speed\": 0.7, \"wait\": 0.3}, {\"text\": \"두번째 인물 장영실\", \"tune\": 20, \"echo\": 0.2, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"조선시대를 과학의 길로 이끈 과학자\", \"tune\": 19, \"echo\": 0.2, \"speed\": 0.7, \"wait\": 0.3}, {\"text\": \"세번째 인물 송상현  우레 동네 부산을\", \"tune\": 19, \"echo\": 0.7, \"speed\": 0.9, \"wait\": 0.3}, {\"text\": \"위해 용감히 싸워주신 용감한 장군\", \"tune\": 20, \"echo\": 0.1, \"speed\": 0.7, \"wait\": 0.3}, {\"text\": \"동래구 세 영웅 덕분에 우리 동래구가 빛난다\", \"tune\": 20, \"echo\": 0.1, \"speed\": 0.6, \"wait\": 0.3}]',5,'1023','2026-06-26 08:07:50'),
('p1782461291675','샘플','김샘플','야르초','f2','민서','/static/mr/Broken Circuits - Telecasted.mp3','[{\"text\": \"동래 성벽 위에 서 조선 지키려 했네\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.2}, {\"text\": \"백성 위해 불꽃처럼 빛나내\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"폭풍 속에서고 변치 않는 정의의 길\", \"tune\": 20, \"echo\": 0.7, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"송상현의 이름은 빛나네\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"용감한 정신,그의 유산은 forevr\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"그의 정신은 오늘 까지 울려 퍼진다\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}]',2,'segyejeon1012!','2026-06-26 08:08:12'),
('p1782461293308','청소년 센터','일본인이 신맛을 먹을때 하는말은 와따시노~~','청소년 센터','f4','서현','/static/mr/Cooked - Dyalla.mp3','[{\"text\": \"하하웃는 친구들이 센터오는 소리\", \"tune\": 5, \"echo\": 0, \"speed\": 0.9, \"wait\": 0.2}, {\"text\": \"친구들 하고 게임도하고 노래도부를수있는 수련관\", \"tune\": 4, \"echo\": 0, \"speed\": 0.9, \"wait\": 0.2}, {\"text\": \"수련관은 성실하고 선생님들 친절함\", \"tune\": 5, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.2}, {\"text\": \"오면 재미있는것들도 많다\", \"tune\": 4, \"echo\": 0, \"speed\": 0.7, \"wait\": 0.2}, {\"text\": \"오시면 중독돼는 우리 센터\", \"tune\": 6, \"echo\": 0, \"speed\": 0.7, \"wait\": 0.2}, {\"text\": \"여기로 오세요 청소년센터\", \"tune\": 5, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.2}]',1,'shfochlrh','2026-06-26 08:08:13'),
('p1782461297814','별빛아래의 과학자','누구누구','청소년 수련관','f2','민서','/static/mr/Broken Circuits - Telecasted.mp3','[{\"text\": \"밤하늘 별빛아래 영감을 준 과학자 장영실의 history\", \"tune\": 18, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.2}, {\"text\": \"혼수대에서 빚어진 꿈,혼수대의 지혜가 달린 유물, 시간을 초월해.\", \"tune\": 8, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}, {\"text\": \"깊은 밤에 홀로 빛나는 보석,장영실\", \"tune\": 8, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}, {\"text\": \"시간의 흐름을 가르는 조선의 시계\", \"tune\": 8, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}, {\"text\": \"조선의 과학 정신이 빛나는 보석,장영실\", \"tune\": 8, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}, {\"text\": \"그의 손길이 담긴 유물,영원히 빛날거야\", \"tune\": 8, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.3}]',2,'150926','2026-06-26 08:08:17'),
('p1782461359056','샘플','김샘플','샘플초등학교','f2','민서','/static/mr/No Rush - Dyalla.mp3','[{\"text\": \"동래 성벽 위에 서 조선 지키려 했네\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.2}, {\"text\": \"백성 위해 불꽃처럼 빛나내\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"폭풍 속에서고 변치 않는 정의의 길\", \"tune\": 20, \"echo\": 0.7, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"송상현의 이름은 빛나네\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"용감한 정신,그의 유산은 forevr\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"그의 정신은 오늘 까지 울려 퍼진다\", \"tune\": 20, \"echo\": 1, \"speed\": 2, \"wait\": 0.3}]',3,'segyejeon1012!','2026-06-26 08:09:19'),
('p1782461406870','송상현 형님','쌍쌍이','?','f1','수진','/static/mr/Cosy - Dyalla.mp3','[{\"text\": \"충성의 빛으로 어둠을 빛추는 송상현\", \"tune\": 5, \"echo\": 0, \"speed\": 0.9, \"wait\": 0.1}, {\"text\": \"평화을 위한 싸움\", \"tune\": 8, \"echo\": 0, \"speed\": 1, \"wait\": 0.1}, {\"text\": \"송상현을 영웅으로 섬기거라\", \"tune\": 5, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"그에 에국심은 아직도 빛난다\", \"tune\": 4, \"echo\": 0.3, \"speed\": 0.7, \"wait\": 0.3}, {\"text\": \"그에 마음은 영원히\", \"tune\": 8, \"echo\": 0, \"speed\": 0.7, \"wait\": 0.3}]',3,'0901','2026-06-26 08:10:06'),
('p1782461411208','구포성의 밤','블랙킁킁이 만든사람','개인','f2','민서','/static/mr/Broken Circuits - Telecasted.mp3','[{\"text\": \"밤하늘 별빛아래,구포성의 벽동이 은은하게 빛나내\", \"tune\": 10, \"echo\": 0.1, \"speed\": 1.1, \"wait\": 0.1}, {\"text\": \"옛성채의 문이 열려 바람에 춤추는 달빛아래\", \"tune\": 4, \"echo\": 0.1, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"산 봉우리 향해 오르는 길 하늘을 향해 뻗어 나가는 의지\", \"tune\": 4, \"echo\": 0.1, \"speed\": 0.9, \"wait\": 0.3}]',3,'7676','2026-06-26 08:10:11'),
('p1782461489035','빛나는 학춤의 꿈','프린세스','개인','f3','유나','/static/mr/Boom - Dyalla.mp3','[{\"text\": \"동래 학춤의 몸짓과 춤사위, 햇살 아래 빛나네\", \"tune\": 9, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.2}, {\"text\": \"옛 전통에 뿌리깊은 손길로 펼쳐가네\", \"tune\": 9, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"마을 축제 속 학춤, 함께 춤추며 노래하네\", \"tune\": 8, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"하늘의 학처럼 높이 날아 오르며 희망을 전하네\", \"tune\": 8, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"현대에도 이어지는 꿈과 열정, 학춤의 노래\", \"tune\": 7, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}, {\"text\": \"동래의 미래, 학춤으로 빛나는 역사를 이어가네\", \"tune\": 6, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.3}]',2,'osh0412^^','2026-06-26 08:11:29'),
('p1782461527696','기억의 억덕','한국','개인','f2','민서','/static/mr/Kicking It - Dyalla.mp3','[{\"text\": \"기억의 언덕 위에 서서 바람에 날리는 추억들\", \"tune\": 10, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.2}, {\"text\": \"역사의 그늘아래 그들의 영혼을 부르며\", \"tune\": 10, \"echo\": 0, \"speed\": 0.5, \"wait\": 0.2}, {\"text\": \"돌탑 위에 서있는 그림자 일제강점기의 시간 속에 전사들의 이야기\", \"tune\": 10, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1, \"wait\": 0.3}]',2,'99','2026-06-26 08:12:08'),
('p1782462138691','용감한 청소년센터','일본인이 신맛을 먹을때 하는말은 와따시노~~','청소년 센터','f3','유나','/static/mr/Sunny Days - Anno Domini Beats.mp3','[{\"text\": \"하하웃는 친구들이 센터에 오는소리\", \"tune\": 4, \"echo\": 0, \"speed\": 0.7, \"wait\": 0.1}, {\"text\": \"친구들하고 게임하고노래도부르수도맀다\", \"tune\": 3, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.2}, {\"text\": \"센터는 성실하고 좋은선생님들\", \"tune\": 5, \"echo\": 0, \"speed\": 0.9, \"wait\": 0.1}, {\"text\": \"오면 재미있는것등도있다\", \"tune\": 5, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.1}, {\"text\": \"오시면 중독돼요 우리는센터\", \"tune\": 3, \"echo\": 0, \"speed\": 0.8, \"wait\": 0.1}, {\"text\": \"여기로 오세요 청소년센터\", \"tune\": 5, \"echo\": 0, \"speed\": 1, \"wait\": 0.1}]',1,'123456789','2026-06-26 08:22:18'),
('p1782462169985','동래의 향기','윤동희','꼴데','f3','유나','/static/mr/No Rush - Dyalla.mp3','[{\"text\": \"부산의 향기,그 속엔 역사가 스며들어.\", \"tune\": 7, \"echo\": 0, \"speed\": 0.9, \"wait\": 0.2}, {\"text\": \"동래의 노래,세대를 잇는 푸른길\", \"tune\": 7, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"밤이 깊어도 꺼지지않는 그 불빛\", \"tune\": 8, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}, {\"text\": \"동래읍성의 아름다움,영원히 간직 되리라\", \"tune\": 8, \"echo\": 0, \"speed\": 1, \"wait\": 0.3}]',0,'qwer','2026-06-26 08:22:50'),
('p1782462353749','다메다메','샤샤넬','샤샤넬','f2','민서','/static/mr/Broken Circuits - Telecasted.mp3','[{\"text\": \"다메다메다메\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.9, \"wait\": 0.2}, {\"text\": \"요시타이 모레도레\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.6, \"wait\": 0.3}, {\"text\": \"모레쿠라\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.5, \"wait\": 0.3}, {\"text\": \"다메다메다메 머시도저\", \"tune\": 8, \"echo\": 0.2, \"speed\": 2, \"wait\": 0.3}, {\"text\": \"시쿠레도목시도레미\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.3, \"wait\": 0.3}]',1,'segyejeon1012','2026-06-26 08:25:54'),
('p1782462533238','웃어줘','샤샤넬','샤샤넬','f3','유나','/static/mr/Broken Circuits - Telecasted.mp3','[{\"text\": \"웃어주세요\", \"tune\": 18, \"echo\": 0.1, \"speed\": 1.1, \"wait\": 0.2}, {\"text\": \"웃어주세요\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.6, \"wait\": 0.3}, {\"text\": \"웃어주세요\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1.5, \"wait\": 0.3}, {\"text\": \"웃어주세요\", \"tune\": 8, \"echo\": 0.2, \"speed\": 1, \"wait\": 0.3}]',0,'a','2026-06-26 08:28:53');
