(22,NULL,'2일차','',NULL,'Ocean University',NULL,NULL,30,NULL,'active',NULL,0,'2026-07-31 11:17:34','2026-08-14 02:04:14','[{\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"int buzzerPin = 8;\\n\\nvoid setup() {\\n  pinMode(buzzerPin, OUTPUT);\\n}\\n\\nvoid loop() {\\n\\n  tone(buzzerPin, 262); \\n  delay(500);\\n\\n  noTone(buzzerPin);\\n  delay(1000); \\n}\", \"language\": \"arduino\", \"title\": \"\\ubd80\\uc800\\ubaa8\\ub4c8 \\ub3d9\\uc791 \\ucf54\\ub4dc\", \"_morder\": 50, \"chapter\": \"2 - \\ubcc0\\uc218 \\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/1bd0c11be41b409482814d75a6e1f62e.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"\\ubcc0\\uc218\\ub780?sdsdsd\", \"_morder\": 20, \"chapter\": \"2 - \\ubcc0\\uc218 \\ub780?\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"int Gas = A0;\\n\\nvoid setup() {\\n\\n  Serial.begin(9600);\\n  pinMode(Gas,INPUT);\\n\\n}\\n\\nvoid loop() {\\n\\n  int GasValue = analogRead(Gas);\\n  \\n\\n  Serial.print(\\\"Raw Value: \\\");\\n  Serial.println(GasValue);\\n\\n\\n  delay(1000);\\n}\", \"language\": \"arduino\", \"title\": \"\\uc774\\uc0b0\\ud654\\ud0c4\\uc18c \\uc13c\\uc11c \\ucf54\\ub4dcsdasdsd\", \"_morder\": 90, \"chapter\": \"3 - \\uc2dc\\ub9ac\\uc5bc\\ud504\\ub9b0\\ud2b8 \\ub780?\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"  int Water = A2;\\n\\n  int buzzerPin = 8;\\n\\nvoid setup() {\\n\\n  Serial.begin(9600);\\n  pinMode(Water,INPUT);\\n\\n  pinMode(buzzerPin, OUTPUT);\\n\\n}\\n\\nvoid loop() {\\n\\n  int WaterValue = analogRead(Water);\\n  \\n  Serial.print(\\\"Raw Value: \\\");\\n  Serial.println(WaterValue);\\n\\n  if (WaterValue > 95){\\n  tone(buzzerPin, 262); \\n  delay(500);\\n\\n  }else{\\n  noTone(buzzerPin); \\n  }\\n\\n  delay(1000);\\n\\n}\", \"language\": \"arduino\", \"title\": \"\\uc218\\uc9c8\\uad00\\ub9ac\\uc13c\\uc11c \\ucf54\\ub4dc\", \"_morder\": 110, \"chapter\": \"4 - IF\\ubb38 \\uc774\\ub780?\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"#include <Wire.h> \\n#include <LiquidCrystal_I2C.h>\\n\\n// I2C \\uc8fc\\uc18c \\uc124\\uc815 (\\ubcf4\\ud1b5 0x27 \\ub610\\ub294 0x3F), \\uc5f4 16\\uac1c, \\ud589 2\\uac1c\\nLiquidCrystal_I2C lcd(0x27, 16, 2);\\n\\nvoid setup() {\\n\\n  lcd.init();\\n  lcd.backlight();\\n\\n  lcd.setCursor(0, 0);\\n  lcd.print(\\\"Arduino Sensor\\\");\\n\\n  lcd.setCursor(0, 1);\\n  lcd.print(\\\"System Ready!\\\");\\n}\\n\\nvoid loop() {\\n\\n}\", \"language\": \"arduino\", \"title\": \"LCD\\ubaa8\\ub4c8 \\ub3d9\\uc791 \\ucf54\\ub4dc\", \"_morder\": 140, \"chapter\": \"5 - \\ub77c\\uc774\\ube0c\\ub7ec\\ub9ac \\ub780?\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \" int MOTOR_A1 = 4;\\n int MOTOR_A2 = 5;\\n\\nvoid setup() {\\n\\n  Serial.begin(9600);\\n\\n  pinMode(MOTOR_A1, OUTPUT);\\n  pinMode(MOTOR_A2, OUTPUT);\\n\\n}\\n\\nvoid loop() {\\n\\n  digitalWrite(MOTOR_A1, HIGH);\\n  digitalWrite(MOTOR_A2, LOW);\\n  delay(1000);\\n\\n}\", \"language\": \"arduino\", \"title\": \"DC \\ubaa8\\ud130 \\ub3d9\\uc791 \\ucf54\\ub4dc\", \"_morder\": 160, \"chapter\": \"6 - DC\\ubaa8\\ud130 \\ub2e4\\uc911 \\uc81c\\uc5b4\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/59841ab12f1c41ea9162c2c028d9b105.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"IF\\ubb38 \\uc774\\ub780?\", \"_morder\": 70, \"chapter\": \"4 - IF\\ubb38 \\uc774\\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/5866a35b47e7452495e5dfb3255660fe.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"\\ub77c\\uc774\\ube0c\\ub7ec\\ub9ac \\ub780?\", \"_morder\": 120, \"chapter\": \"5 - \\ub77c\\uc774\\ube0c\\ub7ec\\ub9ac \\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/6e84ef9921e841c2ae2325d7ce91470c.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"\\uc2dc\\ub9ac\\uc5bc\\ud504\\ub9b0\\ud2b8 \\ub780?\", \"_morder\": 60, \"chapter\": \"3 - \\uc2dc\\ub9ac\\uc5bc\\ud504\\ub9b0\\ud2b8 \\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/db0e69fec2c1442abc38f7c9d47eb2b0.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"DC \\ubaa8\\ud130 \\ubc30\\uc120 \\uc5f0\\uacb0\", \"_morder\": 150, \"chapter\": \"6 - DC\\ubaa8\\ud130 \\ub2e4\\uc911 \\uc81c\\uc5b4\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/870293c128e044c0a3ccab36b5d71fea.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"LCD \\ubc30\\uc120 \\uc5f0\\uacb0\", \"_morder\": 130, \"chapter\": \"5 - \\ub77c\\uc774\\ube0c\\ub7ec\\ub9ac \\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/32b1b5f2076b40dfa456e6098979148e.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"\\uc218\\uc9c8\\uad00\\ub9ac \\uc13c\\uc11c \\ubc30\\uc120 \\uc5f0\\uacb0\", \"_morder\": 100, \"chapter\": \"4 - IF\\ubb38 \\uc774\\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/44a87cceb2e74752b34b3761ce98f517.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"\\uc774\\uc0b0\\ud654\\ud0c4\\uc18c \\uc13c\\uc11c \\ubc30\\uc120 \\uc5f0\\uacb0\", \"_morder\": 80, \"chapter\": \"3 - \\uc2dc\\ub9ac\\uc5bc\\ud504\\ub9b0\\ud2b8 \\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/b53beccd504c48b1bc342b4fdae3a6a7.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"\\ubd80\\uc800 \\ubaa8\\ub4c8 \\ubc30\\uc120 \\uc5f0\\uacb0\", \"_morder\": 30, \"chapter\": \"2 - \\ubcc0\\uc218 \\ub780?\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/817cf3212b644a6faf993228bcc20aa0.jpg\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"VIBE \\ucf54\\ub529 \\uc544\\uc774\\ub514\\uc5b4 \\ucc3d\\uc791!\", \"_morder\": 170, \"chapter\": \"7 - \\uc544\\uc774\\ub514\\uc5b4 \\ucc3d\\uc791 \\ud558\\uae30!\"}]'),
(23,NULL,'3일차','',NULL,'Ocean University',NULL,NULL,30,NULL,'active',NULL,0,'2026-07-31 11:17:41','2026-09-09 10:33:14','[{\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"#include <SoftwareSerial.h>\\n\\n#include <LiquidCrystal_I2C.h> //LCD\\uc81c\\uc5b4\\ub97c \\uc704\\ud55c \\ub77c\\uc774\\ube0c\\ub7ec\\ub9ac\\n\\n\\nSoftwareSerial BTSerial(2,3);//(TX,RX)\\n\\nLiquidCrystal_I2C lcd(0x27, 16, 2); //LCD\\ub97c \\uc120\\uc5b8\\ud55c\\ub2e4\\n\\n\\nint LL =4;\\nint LR =5;\\nint RL =6;\\nint RR =7;\\n\\nint Fire = A0;\\nint Water = A2;\\n\\nint Bu =8;\\n\\n\\nvoid setup()\\n{\\n Serial.begin(9600);\\n BTSerial.begin(9600);\\n \\n   lcd.init();                    // I2C LCD\\uc758 \\ucd08\\uae30\\ud654\\n  lcd.backlight();              // I2C LCD\\uc758 \\ubc31\\ub77c\\uc774\\ud2b8 \\ucf1c\\uae30\\n\\n  pinMode(LL, OUTPUT);\\n  pinMode(LR, OUTPUT);\\n  pinMode(RL, OUTPUT);\\n  pinMode(RR, OUTPUT);\\n\\n  pinMode(Bu, OUTPUT);\\n\\n  pinMode(Fire, INPUT);\\n  pinMode(Water, INPUT);\\n\\n}\\nvoid loop()\\n{\\n\\n  int FireS = analogRead(Fire);\\n  int WaterS = analogRead(Water);\\n\\n  char command;\\n  while (BTSerial.available()>0)\\n  command=BTSerial.read();\\n  Serial.println(command);\\n   if(command == \'\'g\'\'){             //\\uc804\\uc9c4\\n      analogWrite(LL, 150); //\\uc67c\\ucabd\\ubaa8\\ud130\\uc758 \\uc67c\\ucabd\\ud540\\uc5d0 \\uac12\\uc785\\ub825\\n      analogWrite(LR, 0);\\n      analogWrite(RL, 0);\\n      analogWrite(RR, 150);\\n    }else if(command== \'\'k\'\'){       //\\ud6c4\\uc9c4\\n      analogWrite(LL, 0); //\\uc67c\\ucabd\\ubaa8\\ud130\\uc758 \\uc67c\\ucabd\\ud540\\uc5d0 \\uac12\\uc785\\ub825\\n      analogWrite(LR, 150);\\n      analogWrite(RL, 150);\\n      analogWrite(RR, 0);\\n    }else if(command== \'\'r\'\'){       //\\uc624\\ub978\\n      analogWrite(LL, 150); //\\uc67c\\ucabd\\ubaa8\\ud130\\uc758 \\uc67c\\ucabd\\ud540\\uc5d0 \\uac12\\uc785\\ub825\\n      analogWrite(LR, 0);\\n      analogWrite(RL, 150);\\n      analogWrite(RR, 0);\\n    }else if(command== \'\'l\'\'){       //\\uc67c\\ucabd\\n      analogWrite(LL, 0); //\\uc67c\\ucabd\\ubaa8\\ud130\\uc758 \\uc67c\\ucabd\\ud540\\uc5d0 \\uac12\\uc785\\ub825\\n      analogWrite(LR, 150);\\n      analogWrite(RL, 0);\\n      analogWrite(RR, 150);\\n    }else if(command== \'\'s\'\'){       //\\uc815\\uc9c0\\n      analogWrite(LL, 0); //\\uc67c\\ucabd\\ubaa8\\ud130\\uc758 \\uc67c\\ucabd\\ud540\\uc5d0 \\uac12\\uc785\\ub825\\n      analogWrite(LR, 0);\\n      analogWrite(RL, 0);\\n      analogWrite(RR, 0);\\n    }\\n  \\n    //LCD\\uc5d0 \\ucd9c\\ub825\\ud560 \\uc2b5\\ub3c4 \\uba54\\uc138\\uc9c0\\ub97c \\ub9cc\\ub4ed\\ub2c8\\ub2e4.\\n  String Firet = \\\"F:\\\";\\n  Firet += (FireS);\\n  Firet += \\\"%\\\";\\n\\n  //LCD\\uc5d0 \\ucd9c\\ub825\\ud560 \\uc2b5\\ub3c4 \\uba54\\uc138\\uc9c0\\ub97c \\ub9cc\\ub4ed\\ub2c8\\ub2e4.\\n  String Watert = \\\"W:\\\";\\n  Watert += (WaterS);\\n  Watert += \\\"%\\\";\\n\\n\\nSerial.println(WaterS);\\n\\n\\n\\n  lcd.setCursor(0, 0);\\n  lcd.print(Firet);\\n\\n  lcd.setCursor(8, 0);\\n  lcd.print(Watert);\\n\\n  if(FireS > 450){\\n  lcd.setCursor(0, 1);\\n  lcd.print(\\\"Dangers\\\");\\n  tone(Bu, 50);\\n\\n  }else{\\n  lcd.setCursor(0, 1);\\n  lcd.print(\\\"Safety\\\");\\n  noTone(Bu);\\n  }\\n\\n  if(WaterS < 100){\\n  lcd.setCursor(8, 1);\\n  lcd.print(\\\"Safety\\\");\\n  noTone(Bu);\\n  }else{\\n  lcd.setCursor(8, 1);\\n  lcd.print(\\\"Dangers\\\");\\n  tone(Bu, 112);\\n  }\\n\\n  \\n  while (Serial.available())\\n    BTSerial.write(Serial.read());\\n\\n\\n\\n\\n}\\n\", \"language\": \"arduino\", \"_morder\": 20, \"title\": \"\\ud574\\uc591 \\uc0dd\\ud0dc \\ud55c\\ub098\\ub77c\\ud638 (\\ub3d9\\uc791\\ucf54\\ub4dc)\"}]'),
(31,NULL,'피지컬 AI 지도사 1주차 - (디지털 피아노)','',NULL,'physical_ai_instructor_level_2',NULL,NULL,30,NULL,'active',NULL,0,'2026-08-28 08:54:28','2026-08-28 09:05:05','[]'),
(32,NULL,'피지컬 AI 지도사 2주차 - (디지털 피아노)','',NULL,'physical_ai_instructor_level_2',NULL,NULL,30,NULL,'active',NULL,0,'2026-08-28 09:04:53','2026-08-29 03:09:42','[{\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"tone(7,262);\", \"language\": \"arduino\", \"title\": \"\\ubd80\\uc800 \\ubaa8\\ub4c8 \\ub3d9\\uc791 \\ucf54\\ub529!\", \"_morder\": 50, \"chapter\": \"\\ubd80\\uc800\\ubaa8\\ub4c8 \\ucf54\\ub4dc\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"noTone(7);\", \"language\": \"arduino\", \"title\": \"\\ubd80\\uc800 \\ubaa8\\ub4c8 \\ubbf8\\ub3d9\\uc791 \\ucf54\\ub529!\", \"_morder\": 60, \"chapter\": \"\\ubd80\\uc800\\ubaa8\\ub4c8 \\ucf54\\ub4dc\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"BT.print(t10,e11);\", \"language\": \"arduino\", \"title\": \"\\ucd08\\uc74c\\ud30c \\uc13c\\uc11c \\ub3d9\\uc791 \\ucf54\\ub4dc!\", \"_morder\": 80, \"chapter\": \"\\ubd80\\uc800\\ubaa8\\ub4c8 \\ucf54\\ub4dc\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"Piano.mode\", \"language\": \"arduino\", \"title\": \"\\uc804\\uccb4\\ub3d9\\uc791 \\ucf54\\ub4dc!\", \"_morder\": 100, \"chapter\": \"\\uc804\\uccb4 \\ub3d9\\uc791 \\ucf54\\ub4dc\"}, {\"type\": \"image\", \"content\": \"\", \"url\": \"/uploads/d09bfa7a278d430ea89470c4d1eb5e66.png\", \"caption\": \"\", \"level\": 3, \"code\": \"\", \"language\": \"python\", \"title\": \"\\ud53c\\uc544\\ub178 \\uc8fc\\ud30c\\uc218 \\uac12!\", \"_morder\": 30, \"chapter\": \"\\ubd80\\uc800\\ubaa8\\ub4c8 \\ucf54\\ub4dc\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"int buzzerPin = 7;\\n\\nvoid setup() {\\nSerial.begin(9600);\\npinMode(buzzerPin,OUTPUT);\\n\\n}\\n\\nvoid loop() {\\n  tone(buzzerPin, 262);\\n  delay(1000);\\n\\n  noTone(buzzerPin);\\n  delay(1000);\\n}\", \"language\": \"arduino\", \"title\": \"\\ubd80\\uc800 \\uc544\\ub450\\uc774\\ub178 IDE\", \"_morder\": 90, \"chapter\": \"\\uc804\\uccb4 \\ub3d9\\uc791 \\ucf54\\ub4dc\"}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"int trigPin = 10;\\nint echoPin = 11;\\n\\nvoid setup() {\\n  Serial.begin(9600);\\n\\n  pinMode(trigPin, OUTPUT);\\n  pinMode(echoPin, INPUT);\\n}\\n\\nvoid loop() {\\n  // \\ucd08\\uc74c\\ud30c \\ubc1c\\uc0ac\\n  digitalWrite(trigPin, LOW);\\n  delayMicroseconds(2);\\n\\n  digitalWrite(trigPin, HIGH);\\n  delayMicroseconds(10);\\n\\n  digitalWrite(trigPin, LOW);\\n\\n  // \\ucd08\\uc74c\\ud30c\\uac00 \\ub3cc\\uc544\\uc624\\ub294 \\uc2dc\\uac04 \\uce21\\uc815\\n  long duration = pulseIn(echoPin, HIGH);\\n\\n  // \\uac70\\ub9ac \\uacc4\\uc0b0 (cm)\\n  float distance = duration * 0.0343 / 2;\\n\\n  // \\uacb0\\uacfc \\ucd9c\\ub825\\n  Serial.print(\\\"\\uac70\\ub9ac: \\\");\\n  Serial.print(distance);\\n  Serial.println(\\\" cm\\\");\\n\\n  delay(500);\\n}\", \"language\": \"arduino\", \"title\": \"\\ucd08\\uc74c\\ud30c \\uc544\\ub450\\uc774\\ub178 IDE\", \"_morder\": 110, \"chapter\": \"\\ubd80\\uc800\\ubaa8\\ub4c8 \\ucf54\\ub4dc\"}]'),
