(44,NULL,'2회차','',NULL,'voice',NULL,NULL,30,NULL,'active',NULL,0,'2026-10-02 16:56:15','2026-10-02 16:57:42','[{\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"void setup() {\\n\\u00a0 pinMode(7, OUTPUT);\\u00a0\\n}\\nvoid loop() {\\n\\u00a0 tone(7, 262);\\n\\u00a0 delay(1000);\\u00a0\\n\\u00a0 noTone(7);\\n\\u00a0 delay(1000);\\u00a0\\n}\", \"language\": \"arduino\", \"title\": \" 1. \\ubd80\\uc800 \\ubaa8\\ub4c8 \\uae30\\ucd08 \\uc81c\\uc5b4 (\\uc544\\ub450\\uc774\\ub178 IDE)\", \"_morder\": 10}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"int buzzer = 7;\\nvoid setup() {\\n\\u00a0 pinMode(buzzer , OUTPUT);\\u00a0\\n}\\nvoid loop() {\\n\\u00a0 tone(buzzer , 262);\\n\\u00a0 delay(1000);\\u00a0\\n\\u00a0 noTone(buzzer);\\n\\u00a0 delay(1000);\\u00a0\\n}\", \"language\": \"arduino\", \"title\": \"2. \\ubd80\\uc800 \\ubaa8\\ub4c8 \\ubcc0\\uc218 \\uc81c\\uc5b4 (\\uc544\\ub450\\uc774\\ub178 IDE)\", \"_morder\": 20}, {\"type\": \"code\", \"content\": \"\", \"url\": \"\", \"caption\": \"\", \"level\": 3, \"code\": \"int buzzer = 7;\\nvoid setup() {\\n\\u00a0 pinMode(buzzer , OUTPUT);\\u00a0\\n}\\nvoid loop() {\\n\\u00a0 tone(buzzer , 262)\\n\\u00a0 delay(1000);\\u00a0\\n\\u00a0 noTone(buzzer)\\n\\u00a0 delay(1000);\\u00a0\\n}\", \"language\": \"arduino\", \"title\": \"3. \\ub204\\ube44\\ub2e4 AI \\ud14c\\uc2a4\\ud2b8\\u00a0(\\uc544\\ub450\\uc774\\ub178 IDE)\", \"_morder\": 30}]');
